151	        format!("custom.{}", self.identifier)
152	    }
153	
154	    fn action(
155	        &self,
156	        key: super::Key,
157	        selection: super::TextRange,
158	        context: impl ActionContext,
159	    ) -> Option<Action> {
160	        let _target_id = context.get_node_id_at(&key, selection.start.line as usize)?;
161	        Some(Action {
162	            title: self.title.clone(),
163	            identifier: self.identifier(),
164	            key: key.clone(),
165	            range: selection.clone(),
166	        })
167	    }
168	
169	    fn changes(
170	        &self,
171	        key: super::Key,
172	        selection: super::TextRange,
173	        context: impl ActionContext,
174	    ) -> Option<Changes> {
175	        let target_id = context.get_node_id_at(&key, selection.start.line as usize)?;
176	
177	        let tree = &context.collect(&key);
178	
179	        let target_id = tree
180	            .get_surrounding_top_level_block(target_id)
181	            .unwrap_or(target_id);
182	
183	        let input = templates::render_input_template(&self.input_template, target_id, tree);
184	
185	        let command = context.get_command(&self.command)?;
186	
187	        if command.run.is_empty() {
188	            return None;
189	        }
190	
191	        let generated = execute_command(command, &input)?;
192	
193	        let mut patch = context.patch();
194	
195	        patch.from_markdown("new".into(), &generated, MarkdownReader::new());
196	        let tree = patch.maybe_key(&"new".into()).unwrap().collect_tree();
197	
198	        let markdown = context
199	            .collect(&key)
200	            .replace(target_id, &tree)
201	            .iter()
202	            .to_markdown(&key.parent(), context.markdown_options());
203	
204	        Some(Changes::new().update(key, markdown))
205	    }
206	}
